  "privWhat1": "Когато създадете профил, използваме вашия имейл, идентификатор на профила, записи за удостоверяване с парола и статус на потвърждение, за да предоставяме и защитаваме профила ви. Паролите се обработват от доставчика на удостоверяване като сигурни хешове; Cook не съхранява четими пароли. Съхраняваме разположението на кухнята, избрания език, темата и мерните единици, за да възстановим настройките ви на всички устройства. За профил са нужни имейл и парола; можете да разглеждате рецепти и без профил.",
  "privWhat2": "Обработването на профила и настройките е необходимо, за да предоставим поисканата от вас услуга за профил (член 6, параграф 1, буква „б“ от ОРЗД). Ограничени записи за сигурност и предотвратяване на злоупотреби могат да се обработват на основание легитимни интереси (член 6, параграф 1, буква „е“), доколкото е необходимо и след претегляне на интересите. Имейлите за потвърждение и нулиране на парола са служебни съобщения, а не маркетинг. Функцията за профил не добавя реклама или анализ.",
  "privStorage1": "Cook използва sessionStorage, за да пренася кухнята, напредъка в готвенето и изборите ви между страниците в същия раздел. Когато сте влезли, там се пази и сесията ви за вход. Браузърът обикновено изчиства това при края на сесията на раздела, но възстановяването на сесии в браузъра може да го запази. Излизането изчиства данните на Cook в раздела. Затварянето на известието за хранилището се помни само в този раздел. Собствените скриптове на Cook не задават бисквитки. Доставчиците ви на хостинг или услуги може да извършват собствено обработване за сигурност, което трябва да се документира преди пускането.",
  "privStorage2": "OK и бутонът за затваряне на известието за хранилището само затварят известието. Те не разрешават анализ, реклама или друго незадължително проследяване. Всяко бъдещо несъществено съхранение ще изисква отделен избор преди започването си, с еднакво лесен отказ и оттегляне.",
  "privOther1": "Текущата гласова функция на списъка с рецепти запитва country.is за приблизителна държава по вашия IP адрес, за да избере език за разпознаване на говор. Ако използвате разпознаване чрез микрофон, браузърът ви може да изпраща звук към своя доставчик на разпознаване на говор. Можете също да въвеждате съставките. Тези доставчици, техните политики и правното основание за тези функции трябва да бъдат прегледани преди публичното пускане.",
  "privProviders1": "Планиран доставчик на профили: Supabase (управляван PostgreSQL и удостоверяване) с избран регион на базата данни в ЕС. Доставчик на имейл: [доставчик]. Хостинг на сайта: [доставчик]. Администраторът трябва да потвърди действителните доставчици, договорите за обработване, подизпълнителите, местоположението на журналите и всяко предаване извън ЕИП. Регион на базата данни в ЕС сам по себе си не изключва международни предавания. Когато е приложимо, посочете приложимото решение за адекватност или договорните гаранции и как да се получи копие.",
  "privRetention1": "Настройките на профила се пазят, докато профилът ви е активен. Можете да поискате изтриване чрез посочения по-горе контакт за поверителност. Преди пускането администраторът трябва да определи реда за отговор на искания за изтриване, изтичането на непотвърдени профили и сроковете за съхранение на журналите за сигурност и резервните копия. Изтритите данни може да останат в резервни копия с ограничен достъп до края на документирания срок на съхранение.",
  "privRights1": "В зависимост от приложимите условия можете да поискате достъп, коригиране, изтриване, ограничаване или преносимост или да възразите срещу обработване въз основа на легитимен интерес. Свържете се с посочения по-горе администратор; на исканията обикновено се отговаря в рамките на един месец, като всяко законно удължаване се обяснява. Можете да подадете жалба до надзорния орган, включително унгарския NAIH на naih.hu. Cook не използва настройките на профила за автоматизирани решения с правни или подобно значими последици.",
